import { z } from "zod";

// Photos and PDFs a person attaches to a chat message. Files live in the private "chat" bucket under the workspace id.
export const ATTACHMENT_TYPES = { "image/jpeg": "jpg", "image/png": "png", "image/webp": "webp", "application/pdf": "pdf" } as const;
export type AttachmentType = keyof typeof ATTACHMENT_TYPES;
export const MAX_ATTACHMENTS = 4;
/** Sent when someone attaches files without typing anything. */
export const ATTACHMENT_ONLY_MESSAGE = "Here is a file I attached.";
/** Under the 4.5 MB serverless request limit; photos are downscaled before upload. */
export const MAX_ATTACHMENT_BYTES = 4 * 1024 * 1024;

export const attachmentSchema = z.object({
  path: z.string().regex(/^[0-9a-f-]{36}\/[0-9a-f-]{36}\.(?:jpg|png|webp|pdf)$/),
  name: z.string().trim().min(1).max(200),
  type: z.enum(Object.keys(ATTACHMENT_TYPES) as [AttachmentType, ...AttachmentType[]]),
}).strict();
export type ChatAttachment = z.infer<typeof attachmentSchema>;

/** The file's real type from its first bytes, so a renamed file cannot pass as another. */
export function sniffType(bytes: Uint8Array): AttachmentType | null {
  const starts = (...signature: number[]) => signature.every((byte, index) => bytes[index] === byte);
  if (starts(0xff, 0xd8, 0xff)) return "image/jpeg";
  if (starts(0x89, 0x50, 0x4e, 0x47)) return "image/png";
  if (starts(0x52, 0x49, 0x46, 0x46) && String.fromCharCode(...bytes.slice(8, 12)) === "WEBP") return "image/webp";
  if (starts(0x25, 0x50, 0x44, 0x46)) return "application/pdf";
  return null;
}

/** How an earlier message's files appear to the model; only the current message sends file contents. */
export const attachmentNote = (attachments: unknown) => {
  const parsed = z.array(attachmentSchema).safeParse(attachments);
  return parsed.success && parsed.data.length ? `\n[Attached earlier: ${parsed.data.map(item => item.name).join(", ")}]` : "";
};
import { requireWorkspace } from "@/lib/auth";
import { ATTACHMENT_TYPES, MAX_ATTACHMENT_BYTES, attachmentSchema, sniffType } from "@/lib/ai/chat-attachments";

/** Stores one photo or PDF for a chat message and returns its reference. */
export async function POST(request: Request) {
  let context: Awaited<ReturnType<typeof requireWorkspace>>;
  try { context = await requireWorkspace(); } catch { return Response.json({ error: "Unauthorized" }, { status: 401 }); }
  const form = await request.formData().catch(() => null);
  const file = form?.get("file");
  if (!(file instanceof File)) return Response.json({ error: "Choose a file" }, { status: 400 });
  if (file.size > MAX_ATTACHMENT_BYTES) return Response.json({ error: "Files must be under 4 MB" }, { status: 413 });
  const bytes = new Uint8Array(await file.arrayBuffer());
  const type = sniffType(bytes);
  if (!type) return Response.json({ error: "Attach a photo (JPEG, PNG, WebP) or a PDF" }, { status: 415 });
  const path = `${context.workspace.id}/${crypto.randomUUID()}.${ATTACHMENT_TYPES[type]}`;
  const { error } = await context.supabase.storage.from("chat").upload(path, bytes, { contentType: type, upsert: false });
  if (error) return Response.json({ error: error.message }, { status: 400 });
  return Response.json(attachmentSchema.parse({ path, name: file.name.slice(0, 200) || "attachment", type }));
}

/** Serves an attached file; only the owner's workspace folder resolves. It goes through the app because storage is only reachable on the computer running Moneo. */
export async function GET(request: Request) {
  let context: Awaited<ReturnType<typeof requireWorkspace>>;
  try { context = await requireWorkspace(); } catch { return Response.json({ error: "Unauthorized" }, { status: 401 }); }
  const path = new URL(request.url).searchParams.get("path") ?? "";
  if (!attachmentSchema.shape.path.safeParse(path).success || !path.startsWith(`${context.workspace.id}/`)) return Response.json({ error: "Not found" }, { status: 404 });
  const { data, error } = await context.supabase.storage.from("chat").download(path);
  if (error || !data) return Response.json({ error: "Not found" }, { status: 404 });
  // The extension was set from the file's real type on upload.
  const type = Object.entries(ATTACHMENT_TYPES).find(([, extension]) => path.endsWith(`.${extension}`))![0];
  return new Response(data, { headers: { "Content-Type": type, "Cache-Control": "private, no-store", "X-Content-Type-Options": "nosniff" } });
}
import { extractText } from "unpdf";

/** Text sent to the model per PDF; a long statement is cut here, saying so, rather than flooding the context. */
const MAX_PDF_CHARS = 120_000;

/**
 * A PDF's text layer as plain text, one "Page n" section per page, read on this computer. When there is no
 * text (a scan or photo saved as PDF) the note tells the model to say so and ask for photos instead of guessing.
 */
export async function pdfText(bytes: Uint8Array, name: string): Promise<string> {
  let pages: string[];
  try {
    // pdf.js may take ownership of the buffer, so it gets a copy.
    pages = (await extractText(new Uint8Array(bytes), { mergePages: false })).text;
  } catch {
    return `[Attached PDF "${name}" could not be opened. Tell the user you could not read it and ask them to attach photos of its pages instead.]`;
  }
  const body = pages.map((text, index) => `--- Page ${index + 1} ---\n${text.trim()}`).join("\n\n");
  if (!pages.some(text => text.trim())) return `[Attached PDF "${name}" has no readable text, so it is probably a scan. Tell the user you could not read it and ask them to attach photos of its pages instead.]`;
  const cut = body.length > MAX_PDF_CHARS;
  return `[Attached PDF "${name}", ${pages.length} page${pages.length === 1 ? "" : "s"}, text extracted:]\n${cut ? body.slice(0, MAX_PDF_CHARS) : body}${cut ? "\n[The rest of the PDF was cut because it is long. Tell the user only the first part was read.]" : ""}`;
}
