import ExcelJS from "exceljs";
import JSZip from "jszip";
import Papa from "papaparse";
import { createIsomorphicCanvasFactory, extractText, getDocumentProxy } from "unpdf";
import type { AttachmentType } from "@/lib/ai/chat-attachments";

// Every document becomes text on this computer, the same way for every AI source, split into units that
// carry their location: PDF pages, PPTX slides, DOCX paragraphs and spreadsheet rows. Answers cite these
// locations and document_read pages through them.

export type DocumentKind = "pdf" | "docx" | "pptx" | "xlsx" | "csv";
export type DocumentUnit =
  | { kind: "page"; n: number; text: string }
  | { kind: "slide"; n: number; text: string }
  /** A DOCX paragraph or table row; headings carry their level. */
  | { kind: "para"; n: number; text: string; heading?: number }
  /** A spreadsheet row; `sheet` indexes `sheets`, cells start at column A. */
  | { kind: "row"; sheet: number; n: number; cells: string[] };
export type ExtractedDocument = { kind: DocumentKind; units: DocumentUnit[]; sheets?: { name: string; columns: number }[]; pages?: number; scannedPages?: number[] };

export const DOCUMENT_KINDS: Partial<Record<AttachmentType, DocumentKind>> = {
  "application/pdf": "pdf",
  "application/vnd.openxmlformats-officedocument.wordprocessingml.document": "docx",
  "application/vnd.openxmlformats-officedocument.presentationml.presentation": "pptx",
  "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet": "xlsx",
  "text/csv": "csv", "text/tab-separated-values": "csv",
};

/** A PDF page with less text than this has no real text layer (a scan, or a photo saved as PDF). */
const MIN_PAGE_CHARS = 20;
const MAX_CELL_CHARS = 300;

export async function extractDocument(bytes: Uint8Array, type: AttachmentType): Promise<ExtractedDocument> {
  switch (DOCUMENT_KINDS[type]) {
    case "pdf": return extractPdf(bytes);
    case "docx": return extractDocx(bytes);
    case "pptx": return extractPptx(bytes);
    case "xlsx": return extractXlsx(bytes);
    case "csv": return extractCsv(bytes, type === "text/tab-separated-values" ? "\t" : undefined);
    default: throw new Error(`${type} is not a document`);
  }
}

// ---- PDF ----

async function extractPdf(bytes: Uint8Array): Promise<ExtractedDocument> {
  // pdf.js may take ownership of the buffer, so it gets a copy.
  const { text } = await extractText(new Uint8Array(bytes), { mergePages: false });
  const units = text.map((page, index) => ({ kind: "page" as const, n: index + 1, text: page.trim() }));
  return { kind: "pdf", units, pages: units.length, scannedPages: units.filter(unit => unit.text.replace(/\s/g, "").length < MIN_PAGE_CHARS).map(unit => unit.n) };
}

/** PDF pages drawn as JPEG images on this computer, for pages that have no text to read. */
export async function renderPdfPages(bytes: Uint8Array, pages: number[], width = 1400): Promise<{ page: number; image: Uint8Array }[]> {
  const CanvasFactory = await createIsomorphicCanvasFactory(() => import("@napi-rs/canvas"));
  const pdf = await getDocumentProxy(new Uint8Array(bytes), { CanvasFactory } as never);
  const factory = new CanvasFactory();
  const images: { page: number; image: Uint8Array }[] = [];
  try {
    for (const number of pages) {
      const page = await pdf.getPage(number);
      const viewport = page.getViewport({ scale: Math.min(3, width / page.getViewport({ scale: 1 }).width) });
      const drawing = factory.create(viewport.width, viewport.height);
      try {
        // Scans are usually printed on white; a transparent page would turn black as JPEG.
        const context = drawing.context as unknown as CanvasRenderingContext2D;
        context.fillStyle = "#fff"; context.fillRect(0, 0, viewport.width, viewport.height);
        await page.render({ canvas: drawing.canvas as never, canvasContext: context, viewport } as never).promise;
        images.push({ page: number, image: new Uint8Array(await (drawing.canvas as unknown as { encode(format: "jpeg", quality: number): Promise<Uint8Array> }).encode("jpeg", 80)) });
      } finally { factory.destroy(drawing); }
    }
  } finally { await pdf.destroy(); }
  return images;
}

// ---- Office XML ----

type Token = { tag: string; close: boolean; empty: boolean; attrs: string } | { text: string };
const TOKEN = /<(\/?)([A-Za-z_][\w.:-]*)([^>]*?)(\/?)>|<!--[\s\S]*?-->|<\?[\s\S]*?\?>|<!\[CDATA\[([\s\S]*?)\]\]>|([^<]+)/g;

function* xmlTokens(xml: string): Generator<Token> {
  for (const match of xml.matchAll(TOKEN)) {
    if (match[2]) yield { tag: match[2], close: match[1] === "/", empty: match[4] === "/", attrs: match[3] };
    else if (match[5] !== undefined) yield { text: match[5] };
    else if (match[6] !== undefined) yield { text: decodeEntities(match[6]) };
  }
}
const ENTITIES: Record<string, string> = { lt: "<", gt: ">", amp: "&", quot: "\"", apos: "'" };
const decodeEntities = (text: string) => text.replace(/&(#x[0-9a-f]+|#\d+|\w+);/gi, (whole, entity: string) =>
  entity[0] === "#" ? String.fromCodePoint(Number.parseInt(entity.slice(entity[1] === "x" || entity[1] === "X" ? 2 : 1), entity[1] === "x" || entity[1] === "X" ? 16 : 10)) : ENTITIES[entity] ?? whole);
const attribute = (attrs: string, name: string) => { const match = new RegExp(`(?:^|\\s)${name}="([^"]*)"`).exec(attrs); return match ? decodeEntities(match[1]) : undefined; };
const clean = (text: string) => text.replace(/[ \t ]+/g, " ").replace(/ *\n */g, "\n").trim();

async function zipText(zip: JSZip, path: string) {
  const file = zip.file(path);
  if (!file) throw new Error(`The file is missing ${path}`);
  return file.async("string");
}

/** Heading levels by DOCX style id: built-in "heading n" and "Title" styles, or any style with an outline level. */
function headingStyles(stylesXml: string | undefined) {
  const levels = new Map<string, number>();
  for (const match of (stylesXml ?? "").matchAll(/<w:style\b([^>]*)>([\s\S]*?)<\/w:style>/g)) {
    const id = attribute(match[1], "w:styleId");
    if (!id) continue;
    const name = /<w:name w:val="([^"]*)"/.exec(match[2])?.[1]?.toLowerCase() ?? "";
    const outline = /<w:outlineLvl w:val="(\d)"/.exec(match[2])?.[1];
    const level = name === "title" ? 1 : /^heading (\d)$/.exec(name)?.[1] ?? (outline !== undefined ? Number(outline) + 1 : undefined);
    if (level !== undefined) levels.set(id, Number(level));
  }
  return levels;
}

async function extractDocx(bytes: Uint8Array): Promise<ExtractedDocument> {
  const zip = await JSZip.loadAsync(bytes);
  const levels = headingStyles(await zip.file("word/styles.xml")?.async("string"));
  const units: DocumentUnit[] = [];
  const push = (text: string, heading?: number) => { const value = clean(text); if (value) units.push({ kind: "para", n: units.length + 1, text: value, ...(heading ? { heading } : {}) }); };
  let paragraph = "", level: number | undefined, inText = false, tableDepth = 0, cell = "", row: string[] = [];
  for (const token of xmlTokens(await zipText(zip, "word/document.xml"))) {
    if ("text" in token) { if (inText) { if (tableDepth) cell += decodeEntities(token.text); else paragraph += decodeEntities(token.text); } continue; }
    const { tag, close, empty, attrs } = token;
    if (tag === "w:t") inText = !close && !empty;
    else if ((tag === "w:tab" || tag === "w:br" || tag === "w:cr") && !close) { if (tableDepth) cell += " "; else paragraph += tag === "w:tab" ? "\t" : "\n"; }
    else if (tag === "w:pStyle" && !tableDepth) level = levels.get(attribute(attrs, "w:val") ?? "");
    else if (tag === "w:outlineLvl" && !tableDepth) { const value = attribute(attrs, "w:val"); if (value && Number(value) < 9) level = Number(value) + 1; }
    else if (tag === "w:p" && !close && !empty) { if (tableDepth) { if (cell) cell += " "; } else { paragraph = ""; level = undefined; } }
    else if (tag === "w:p" && close && !tableDepth) push(paragraph, level);
    else if (tag === "w:tbl") tableDepth += close ? -1 : 1;
    else if (tag === "w:tc" && close && tableDepth === 1) { row.push(clean(cell).replace(/\n/g, " ")); cell = ""; }
    else if (tag === "w:tr" && !close && tableDepth === 1) row = [];
    else if (tag === "w:tr" && close && tableDepth === 1 && row.some(Boolean)) push(`| ${row.join(" | ")} |`);
  }
  return { kind: "docx", units };
}

/** Paths in .rels files are relative to the folder of the part that owns them. */
function resolvePart(from: string, target: string) {
  const parts = from.split("/").slice(0, -1);
  for (const piece of target.split("/")) { if (piece === "..") parts.pop(); else if (piece !== ".") parts.push(piece); }
  return parts.join("/").replace(/^\//, "");
}
async function relationships(zip: JSZip, part: string) {
  const relsPath = `${part.split("/").slice(0, -1).join("/")}/_rels/${part.split("/").at(-1)}.rels`;
  const xml = await zip.file(relsPath)?.async("string") ?? "";
  return [...xml.matchAll(/<Relationship\b([^>]*)\/?>/g)].map(match => ({ id: attribute(match[1], "Id") ?? "", type: attribute(match[1], "Type") ?? "", target: resolvePart(part, attribute(match[1], "Target") ?? "") }));
}

/** A slide or notes page's text, one line per paragraph; slide-number fields are left out. */
function drawingText(xml: string) {
  let text = "", inText = false, field = 0;
  for (const token of xmlTokens(xml)) {
    if ("text" in token) { if (inText && !field) text += decodeEntities(token.text); continue; }
    if (token.tag === "a:t") inText = !token.close && !token.empty;
    else if (token.tag === "a:fld" && !token.empty) field += token.close ? -1 : 1;
    else if (token.tag === "a:br" && !token.close) text += "\n";
    else if (token.tag === "a:p" && token.close) text += "\n";
  }
  return clean(text).replace(/\n{2,}/g, "\n");
}

async function extractPptx(bytes: Uint8Array): Promise<ExtractedDocument> {
  const zip = await JSZip.loadAsync(bytes);
  const presentation = await zipText(zip, "ppt/presentation.xml");
  const rels = await relationships(zip, "ppt/presentation.xml");
  const order = [...presentation.matchAll(/<p:sldId\b([^>]*)\/?>/g)].map(match => attribute(match[1], "r:id"));
  const slides = order.map(id => rels.find(rel => rel.id === id)?.target).filter((path): path is string => !!path && !!zip.file(path));
  const units: DocumentUnit[] = await Promise.all(slides.map(async (path, index) => {
    const notesPath = (await relationships(zip, path)).find(rel => rel.type.endsWith("/notesSlide"))?.target;
    const notes = notesPath && zip.file(notesPath) ? drawingText(await zipText(zip, notesPath)) : "";
    const text = drawingText(await zipText(zip, path));
    return { kind: "slide" as const, n: index + 1, text: [text, notes && `Speaker notes: ${notes}`].filter(Boolean).join("\n") };
  }));
  return { kind: "pptx", units };
}

// ---- Spreadsheets ----

const cellString = (text: string) => text.replace(/\s*\r?\n\s*/g, " ").trim().slice(0, MAX_CELL_CHARS);

function excelValue(value: ExcelJS.CellValue): string {
  if (value === null || value === undefined) return "";
  if (value instanceof Date) return value.toISOString().replace(/T00:00:00\.000Z$/, "").replace(/\.000Z$/, "Z");
  if (typeof value !== "object") return String(value);
  if ("richText" in value) return value.richText.map(part => part.text).join("");
  if ("error" in value) return String(value.error);
  if ("formula" in value || "sharedFormula" in value) return value.result === undefined ? "" : excelValue(value.result as ExcelJS.CellValue);
  if ("text" in value) return typeof value.text === "string" ? value.text : excelValue(value.text as ExcelJS.CellValue);
  return "";
}

async function extractXlsx(bytes: Uint8Array): Promise<ExtractedDocument> {
  const workbook = new ExcelJS.Workbook();
  await workbook.xlsx.load(Buffer.from(bytes) as never);
  const units: DocumentUnit[] = [], sheets: { name: string; columns: number }[] = [];
  for (const worksheet of workbook.worksheets) {
    const sheet = sheets.length;
    let columns = 0;
    worksheet.eachRow({ includeEmpty: false }, (row, rowNumber) => {
      const cells: string[] = [];
      row.eachCell({ includeEmpty: false }, (cell, column) => { cells[column - 1] = cellString(excelValue(cell.value)); });
      const filled = Array.from(cells, value => value ?? "");
      while (filled.length && !filled.at(-1)) filled.pop();
      if (!filled.length) return;
      columns = Math.max(columns, filled.length);
      units.push({ kind: "row", sheet, n: rowNumber, cells: filled });
    });
    sheets.push({ name: worksheet.name, columns });
  }
  return { kind: "xlsx", units, sheets };
}

/** Bank exports are often Windows-1252 rather than UTF-8. */
function decodeText(bytes: Uint8Array) {
  try { return new TextDecoder("utf-8", { fatal: true }).decode(bytes).replace(/^﻿/, ""); }
  catch { return new TextDecoder("windows-1252").decode(bytes); }
}

function extractCsv(bytes: Uint8Array, delimiter?: string): ExtractedDocument {
  const parsed = Papa.parse<string[]>(decodeText(bytes), { skipEmptyLines: false, ...(delimiter ? { delimiter } : {}) });
  const units: DocumentUnit[] = [];
  let columns = 0;
  parsed.data.forEach((row, index) => {
    const cells = row.map(cellString);
    while (cells.length && !cells.at(-1)) cells.pop();
    if (!cells.length) return;
    columns = Math.max(columns, cells.length);
    units.push({ kind: "row", sheet: 0, n: index + 1, cells });
  });
  return { kind: "csv", units, sheets: [{ name: "", columns }] };
}

import { z } from "zod";

// Where an answer's facts came from in an attached file. The model writes a marker right after the sentence:
//   {{cite a1b2c3d4 p.3}}  {{cite a1b2c3d4 Sheet1!B12 "Rent 950.00"}}  {{cite a1b2c3d4}} (a photo)
// The id is the file's short id; the optional quote is the exact text it relied on. The same locations
// select what document_read returns. Shared by the server and the chat, so it stays free of server code.

export type DocumentLocation =
  | { kind: "page" | "slide" | "para"; from: number; to: number }
  /** Rows and columns are 1-based; no sheet means the first (or a CSV's only) table. */
  | { kind: "cells"; sheet?: string; fromRow: number; toRow: number; fromColumn: number; toColumn: number };

export const columnNumber = (letters: string) => [...letters.toUpperCase()].reduce((total, letter) => total * 26 + letter.charCodeAt(0) - 64, 0);
export function columnLetters(column: number) {
  let letters = "";
  for (let rest = column; rest > 0; rest = Math.floor((rest - 1) / 26)) letters = String.fromCharCode(65 + ((rest - 1) % 26)) + letters;
  return letters;
}
/** A sheet name as Excel writes it in a reference: quoted unless it is a plain word. */
export const sheetPrefix = (sheet: string | undefined) => !sheet ? "" : /^[A-Za-z_][\w.]*$/.test(sheet) ? `${sheet}!` : `'${sheet.replace(/'/g, "''")}'!`;

const MAX_INDEX = 1_000_000;
const RANGE = /^(p|page|slide|para|¶)\.?\s?(\d{1,7})(?:\s?[-–]\s?(\d{1,7}))?$/i;
const CELL = /^([A-Z]{1,3})(\d{1,7})$/i;

export function parseLocation(text: string): DocumentLocation | null {
  const value = text.trim();
  const range = RANGE.exec(value);
  if (range) {
    const kind = range[1].toLowerCase();
    const from = Number(range[2]), to = Number(range[3] ?? range[2]);
    if (from < 1 || to < from || to > MAX_INDEX) return null;
    return { kind: kind === "p" || kind === "page" ? "page" : kind === "slide" ? "slide" : "para", from, to };
  }
  const sheetMatch = /^(?:'((?:[^']|'')+)'|([^!'\s]+))!(.+)$/.exec(value);
  const sheet = sheetMatch ? (sheetMatch[1]?.replace(/''/g, "'") ?? sheetMatch[2]) : undefined;
  const cells = (sheetMatch ? sheetMatch[3] : value).split(":");
  if (cells.length > 2) return null;
  const [start, end] = cells.map(cell => CELL.exec(cell));
  if (!start || (cells.length === 2 && !end)) return null;
  const last = end ?? start;
  const fromColumn = columnNumber(start[1]), toColumn = columnNumber(last[1]), fromRow = Number(start[2]), toRow = Number(last[2]);
  if (fromRow < 1 || toRow < fromRow || toColumn < fromColumn || toRow > MAX_INDEX || toColumn > 16_384) return null;
  return { kind: "cells", ...(sheet ? { sheet } : {}), fromRow, toRow, fromColumn, toColumn };
}

/** How a location reads on a chip: "p.3", "slide 2", "¶12", "Sheet1!B12". */
export function locationLabel(location: DocumentLocation) {
  if (location.kind === "cells") {
    const start = `${columnLetters(location.fromColumn)}${location.fromRow}`, end = `${columnLetters(location.toColumn)}${location.toRow}`;
    return `${sheetPrefix(location.sheet)}${start}${end === start ? "" : `:${end}`}`;
  }
  const span = location.to === location.from ? `${location.from}` : `${location.from}–${location.to}`;
  return location.kind === "page" ? `p.${span}` : location.kind === "slide" ? `slide ${span}` : `¶${span}`;
}

export const citationSchema = z.object({
  id: z.string().regex(/^[0-9a-f]{8}$/),
  location: z.string().max(140).optional(),
  quote: z.string().trim().min(1).max(300).optional(),
}).strict();
export type Citation = z.infer<typeof citationSchema> & { parsed?: DocumentLocation };

/** Matches one marker; groups are id, location and quote. */
export const CITATION_PATTERN = /\{\{cite\s+([0-9a-f]{8})(?:\s+('(?:[^'\n]|'')+'![^\s"{}]+|[^\s"{}]+))?(?:\s+"([^"\n{}]{1,300})")?\s*\}\}/gi;

/** A marker's citation, or null when its parts are not valid. A location that cannot be read is dropped. */
export function parseCitation(match: RegExpMatchArray): Citation | null {
  const parsed = citationSchema.safeParse({ id: match[1].toLowerCase(), location: match[2], quote: match[3] });
  if (!parsed.success) return null;
  const location = parsed.data.location ? parseLocation(parsed.data.location) : null;
  return location ? { ...parsed.data, parsed: location } : { id: parsed.data.id, ...(parsed.data.quote ? { quote: parsed.data.quote } : {}) };
}

/** Markers in model text, for the history the model reads back: kept as they are, so it keeps writing them. */
export const citations = (text: string) => [...text.matchAll(CITATION_PATTERN)].flatMap(match => parseCitation(match) ?? []);

import { columnLetters, locationLabel, parseLocation, sheetPrefix, type DocumentLocation } from "@/lib/ai/citations";
import type { DocumentUnit, ExtractedDocument } from "./extract";

// Documents as the model reads them: a header naming the file, its id and how to cite it, then the text with
// a location on every page, slide, paragraph or row. Long documents are cut at a unit boundary with a note
// naming the next range for document_read.

const KIND_NAMES = { pdf: "PDF", docx: "Word document", pptx: "PowerPoint deck", xlsx: "Excel workbook", csv: "CSV table" } as const;
type RowUnit = Extract<DocumentUnit, { kind: "row" }>;

const escapeCell = (value: string) => value.replace(/\|/g, "\\|");
const plural = (count: number, word: string) => `${count} ${word}${count === 1 ? "" : "s"}`;

function sheetRange(document: ExtractedDocument, sheet: number) {
  const rows = document.units.filter((unit): unit is RowUnit => unit.kind === "row" && unit.sheet === sheet);
  const columns = document.sheets?.[sheet]?.columns ?? 0;
  return rows.length && columns ? `A${rows[0].n}:${columnLetters(columns)}${rows.at(-1)!.n}` : "empty";
}

function overview(document: ExtractedDocument, name: string, id: string) {
  const count = document.kind === "pdf" ? plural(document.pages ?? document.units.length, "page")
    : document.kind === "pptx" ? plural(document.units.length, "slide")
    : document.kind === "docx" ? plural(document.units.length, "paragraph")
    : document.kind === "csv" ? `${plural(document.units.length, "row")} (${sheetRange(document, 0)})`
    : `${plural(document.sheets?.length ?? 0, "sheet")}: ${(document.sheets ?? []).map((sheet, index) => `"${sheet.name}" (${sheetRange(document, index)})`).join(", ")}`;
  const cite = { pdf: "p.N", pptx: "slide.N", docx: "para.N", xlsx: "Sheet!B12", csv: "B12" }[document.kind];
  return `[Document "${name}" (id ${id}), ${KIND_NAMES[document.kind]}, ${count}. Read as text on the owner's computer. Cite it as {{cite ${id} ${cite}}}.]`;
}

/** A row's cells from `from` to `to` (1-based). */
const rowLine = (unit: RowUnit, from = 1, to = unit.cells.length) => `${unit.n} | ${unit.cells.slice(from - 1, to).map(escapeCell).join(" | ")}`;
function sheetHeader(document: ExtractedDocument, sheet: number, from = 1, to = document.sheets?.[sheet]?.columns ?? 1) {
  const name = document.sheets?.[sheet]?.name;
  const columns = Array.from({ length: Math.max(0, to - from + 1) }, (_, index) => columnLetters(from + index)).join(" | ");
  return `=== ${name ? `Sheet "${name}"` : "Table"} (${sheetRange(document, sheet)}) ===\nrow | ${columns}`;
}

function unitText(document: ExtractedDocument, unit: DocumentUnit, imagePages: Set<number>) {
  if (unit.kind === "page") {
    const scanned = document.scannedPages?.includes(unit.n);
    const note = imagePages.has(unit.n) ? "[No text layer: this page is attached as an image after the text.]" : "[No text layer: this page is a scan that was not sent as an image.]";
    return `--- Page ${unit.n} ---\n${scanned ? `${unit.text ? `${unit.text}\n` : ""}${note}` : unit.text}`;
  }
  if (unit.kind === "slide") return `--- Slide ${unit.n} ---\n${unit.text || "[No text on this slide.]"}`;
  if (unit.kind === "para") return unit.heading ? `${"#".repeat(Math.min(unit.heading, 6))} ${unit.text} [¶${unit.n}]` : `[¶${unit.n}] ${unit.text}`;
  return rowLine(unit);
}

function unitLabel(document: ExtractedDocument, unit: DocumentUnit) {
  if (unit.kind === "row") return `${sheetPrefix(document.sheets?.[unit.sheet]?.name)}A${unit.n}`;
  return locationLabel({ kind: unit.kind, from: unit.n, to: unit.n });
}

/** The next stretch after `unit`, written so document_read accepts it. */
function nextRange(document: ExtractedDocument, unit: DocumentUnit) {
  if (unit.kind === "row") {
    const columns = columnLetters(document.sheets?.[unit.sheet]?.columns || 1);
    return `${sheetPrefix(document.sheets?.[unit.sheet]?.name)}A${unit.n}:${columns}${unit.n + 299}`;
  }
  const step = unit.kind === "para" ? 199 : 9;
  return `${unit.kind === "page" ? "p" : unit.kind}.${unit.n}-${unit.n + step}`;
}

/** Units as text within `budget` characters, with sheet headers where a sheet starts and a note where it is cut. */
function renderUnits(document: ExtractedDocument, units: DocumentUnit[], id: string, budget: number, imagePages = new Set<number>(), columns?: [number, number]) {
  const lines: string[] = [];
  let used = 0, sheet = -1;
  for (const [index, unit] of units.entries()) {
    let text = unit.kind === "row" && columns ? rowLine(unit, ...columns) : unitText(document, unit, imagePages);
    if (unit.kind === "row" && unit.sheet !== sheet) { sheet = unit.sheet; text = `${sheetHeader(document, sheet, ...(columns ?? []))}\n${text}`; }
    if (used + text.length > budget && index > 0) {
      const last = units.at(-1)!;
      lines.push(`[Cut here to keep this short: shown up to ${unitLabel(document, units[index - 1])} of ${unitLabel(document, last)}. Read on with document_read, id "${id}", location "${nextRange(document, unit)}".]`);
      break;
    }
    lines.push(text); used += text.length + 1;
  }
  return lines.join(document.kind === "pdf" || document.kind === "pptx" ? "\n\n" : "\n");
}

/** A newly attached document as the model first reads it. */
export function documentForModel(document: ExtractedDocument, name: string, id: string, budget: number, imagePages = new Set<number>()) {
  const body = document.units.length ? renderUnits(document, document.units, id, budget, imagePages) : "[No text could be read from this file.]";
  return `${overview(document, name, id)}\n${body}`;
}

function selectUnits(document: ExtractedDocument, location: DocumentLocation): { units: DocumentUnit[]; columns?: [number, number] } | string {
  if (location.kind === "cells") {
    if (document.kind !== "xlsx" && document.kind !== "csv") return "Cell locations only work for spreadsheets and CSV files.";
    const sheet = location.sheet === undefined ? 0 : (document.sheets ?? []).findIndex(item => item.name.toLowerCase() === location.sheet!.toLowerCase());
    if (sheet < 0) return `There is no sheet "${location.sheet}". Sheets: ${(document.sheets ?? []).map(item => `"${item.name}"`).join(", ")}.`;
    const units = document.units.filter(unit => unit.kind === "row" && unit.sheet === sheet && unit.n >= location.fromRow && unit.n <= location.toRow);
    return { units, columns: [location.fromColumn, location.toColumn] };
  }
  const expected = { page: "pdf", slide: "pptx", para: "docx" }[location.kind];
  if (document.kind !== expected) return `This file is a ${KIND_NAMES[document.kind]}; use ${document.kind === "pdf" ? "p.N" : document.kind === "pptx" ? "slide.N" : document.kind === "docx" ? "para.N" : "cell ranges such as A1:F200"}.`;
  return { units: document.units.filter(unit => unit.kind === location.kind && unit.n >= location.from && unit.n <= location.to) };
}

/** Places where `query` appears, each with its location and a little text around it. */
function search(document: ExtractedDocument, query: string, limit = 40) {
  const needle = query.toLowerCase();
  const found: string[] = [];
  for (const unit of document.units) {
    if (found.length >= limit) break;
    if (unit.kind === "row") {
      unit.cells.forEach((cell, index) => { if (found.length < limit && cell.toLowerCase().includes(needle)) found.push(`${sheetPrefix(document.sheets?.[unit.sheet]?.name)}${columnLetters(index + 1)}${unit.n}: ${rowLine(unit)}`); });
      continue;
    }
    const text = unit.text.replace(/\s+/g, " ");
    for (let at = text.toLowerCase().indexOf(needle); at >= 0 && found.length < limit; at = text.toLowerCase().indexOf(needle, at + needle.length))
      found.push(`${unitLabel(document, unit)}: …${text.slice(Math.max(0, at - 150), at + needle.length + 150)}…`);
  }
  return found;
}

/** What document_read returns: a location range, the places a text appears, or the start of the document. */
export function readDocument(document: ExtractedDocument, input: { name: string; id: string; location?: string; search?: string }, budget = 30_000) {
  const head = overview(document, input.name, input.id);
  if (input.search) {
    const found = search(document, input.search);
    return `${head}\n${found.length ? `"${input.search}" appears at:\n${found.join("\n")}` : `"${input.search}" does not appear in the text. Try a shorter or different word.`}`;
  }
  if (!input.location) return documentForModel(document, input.name, input.id, budget);
  const location = parseLocation(input.location);
  if (!location) return `${head}\nThe location "${input.location}" is not valid. Use p.3 or p.3-5 for PDF pages, slide.2 for slides, para.10-40 for Word paragraphs, or Sheet1!A1:F200 (or A1:F200) for cells.`;
  const selected = selectUnits(document, location);
  if (typeof selected === "string") return `${head}\n${selected}`;
  if (!selected.units.length) return `${head}\nNothing is at ${locationLabel(location)}.`;
  return `${head}\n${renderUnits(document, selected.units, input.id, budget, new Set(), selected.columns)}`;
}

