scalable-mcp.mjs
- `*.smoke.spec.ts` and `*.mocked.spec.ts` stub or skip the backend. Against a configured backend they still need the QA session, like every spec.
- `*.gated.spec.ts` need the backend. Most use the QA session; others create disposable users with the service key, sign them in by session cookie, and remove them in `finally`. If interrupted, their IDs are left in ignored `.qa/` files for cleanup.
- `*.provider.spec.ts` call the real AI model, so they cost money. They run only with `E2E_REAL_AI=1`; `npm run test:e2e` leaves them out.
`scalable-trading.provider.spec.ts` drives chat against a local stand-in for Scalable's MCP server (`e2e/mocks/scalable-mcp.mjs`, made-up data) with the real AI model. Start `npm run qa:server` with `SCALABLE_MCP_ORIGIN=http://127.0.0.1:3043` (and the AI key in `.env.qa`) and run the spec with the same variable and `E2E_REAL_AI=1`; the spec starts the stand-in, adds a Scalable connection to the QA workspace and removes it afterwards. It checks that an order is previewed on a card and sent only when the card is tapped, once, and that read-only access is told it can't trade.
import { test, expect } from "@playwright/test";
import { e2eStorageStatePath, gatedSkipReason, hasSupabaseEnv } from "./fixtures";

const state = e2eStorageStatePath();
if (state) test.use({ storageState: state });
test.skip(!hasSupabaseEnv() || !state, gatedSkipReason());

for (const panel of [false, true]) {
  test(`cancel ${panel ? "contextual panel" : "conversation"} without displaying late work`, async ({ page }) => {
    let release!: () => void;
    const paused = new Promise<void>(resolve => { release = resolve; });
    let submitted: { requestId: string } | undefined;
    await page.route("**/api/chat", async route => {
      if (route.request().method() === "PATCH") {
        expect(route.request().postDataJSON().requestId).toBe(submitted?.requestId);
        await route.fulfill({ json: { status: "canceled" } });
      } else {
        submitted = route.request().postDataJSON();
        await paused;
        await route.fulfill({ json: { answer: "Late answer must stay hidden" } }).catch(() => {});
      }
    });
    await page.goto("/ai?conversation=new");
    if (panel) await page.getByRole("button", { name: "Ask Moneo", exact: true }).click();
    const scope = panel ? page.getByRole("dialog", { name: "AI assistant" }) : page.locator("main");
    await scope.getByLabel(panel ? "Question" : "Ask about your finances").fill("What changed this month?");
    await scope.getByRole("button", { name: "Send", exact: true }).click();
    await expect.poll(() => submitted?.requestId).toBeTruthy();
    await scope.getByRole("button", { name: "Stop", exact: true }).click();
    await expect(scope.getByRole("status").filter({ hasText: "Canceled" })).toBeVisible({ timeout: 15_000 });
    release();
    await expect(scope.getByRole("button", { name: "Send", exact: true })).toBeEnabled();
    await expect(page.getByText("Late answer must stay hidden")).toHaveCount(0);
  });
}

